import { NextResponse } from "next/server";
import { prisma } from "../../../lib/prisma"; // Adjust the path if needed

export async function POST(request) {
  try {
    const { telegramId, points } = await request.json();

    if (!telegramId) {
      return NextResponse.json({ error: "Telegram ID is required." }, { status: 400 });
    }

    // Convert telegramId to an integer
    const telegramIdInt = parseInt(telegramId, 10);

    if (isNaN(telegramIdInt)) {
      return NextResponse.json({ error: "Invalid Telegram ID." }, { status: 400 });
    }

    const user = await prisma.user.findUnique({
      where: { telegramId: telegramIdInt },
    });

    if (!user) {
      return NextResponse.json({ error: "User not found." }, { status: 404 });
    }

    if (user.hasClaimedWelcomePoints) {
      return NextResponse.json(
        { error: "You have already claimed your welcome points." },
        { status: 403 }
      );
    }

    const updatedUser = await prisma.user.update({
      where: { telegramId: telegramIdInt },
      data: {
        points: user.points + points,
        hasClaimedWelcomePoints: true,
        isNewUser: false,
      },
    });

    return NextResponse.json({ success: true, user: updatedUser }, { status: 200 });
  } catch (error) {
    console.error("Error claiming points:", error);
    return NextResponse.json({ error: "Internal Server Error" }, { status: 500 });
  }
}

import {prisma} from '../../../lib/prisma';
import { NextResponse } from 'next/server';

export async function POST(request) {
  try {
    const { userId, taskId, points } = await request.json(); // Destructure points from body

    // Validate and convert `userId` (telegramId) to an integer
    const telegramId = parseInt(userId, 10);
    if (isNaN(telegramId)) {
      return NextResponse.json({ error: 'Invalid user ID.' }, { status: 400 });
    }

    // Find the user by `telegramId`
    const user = await prisma.user.findFirst({
      where: { telegramId },
    });

    if (!user) {
      return NextResponse.json({ error: 'User not found.' }, { status: 404 });
    }

    // Check if the task has already been completed by the user
    const taskCompleted = await prisma.taskCompletion.findFirst({
      where: { userId: user.id, taskId },
    });

    if (taskCompleted) {
      return NextResponse.json({ error: 'Task already completed.' }, { status: 400 });
    }

    // Ensure points value is provided and valid
    if (typeof points !== 'number' || points <= 0) {
      return NextResponse.json({ error: 'Invalid points value.' }, { status: 400 });
    }

    // Create a task completion record
    await prisma.taskCompletion.create({
      data: { userId: user.id, taskId },
    });

    // Increment the user's points with the provided value
    await prisma.user.update({
      where: { id: user.id },
      data: { points: { increment: points } },
    });

    return NextResponse.json({
      success: true,
      message: `Task completed! You earned ${points} points.`,
    });
  } catch (error) {
    console.error('Error completing task:', error);
    return NextResponse.json({ error: 'Internal Server Error' }, { status: 500 });
  }
}

import { NextResponse } from "next/server";
